#include "opensim/framework/animation_set.hpp"
#include <iostream>
using namespace opensim::framework;
namespace {
Uuid id(int n){auto s=std::to_string(n);return Uuid("11223344-5566-7788-99aa-"+std::string(12-s.size(),'0')+s);}
std::string hex(const std::optional<std::string>& s){if(!s)return "NULL";std::string out;for(unsigned char c:*s){out+="0123456789abcdef"[c>>4];out+="0123456789abcdef"[c&15];}return out;}
std::string dump(AnimationSet* model){if(!model)return "NULL";auto bytes=model->to_bytes();std::string raw(bytes->begin(),bytes->end());std::string s=std::to_string(model->animation_count())+":"+hex(raw)+":"+(bytes==AnimationSet::zero_count_bytes?"1":"0");for(auto key:{"a","b","c","d","new","脚 😃"})s+=":"+model->animation(key).str()+":"+hex(model->animation_name(key));return s;}
std::string probe(int mode,int seed,int failure){auto bit=[&](int n){return (mode&n)!=0;};std::string trace,status="OK";std::unique_ptr<AnimationSet> model;auto saved=AnimationSet::zero_count_bytes->at(0);int line=0;try{auto data=std::make_shared<std::vector<std::uint8_t>>(bit(131072)?256:seed%18);for(std::size_t j=0;j<data->size();++j)(*data)[j]=static_cast<std::uint8_t>(bit(131072)?j:seed*13+j*37);if(bit(256)){std::string text="version 1\ncount 1\na "+id(1).str()+" Name\n";data->assign(text.begin(),text.end());}model=std::make_unique<AnimationSet>(bit(128)?AssetBytes{}:data,[&](const auto& s){trace+="|LINE:"+hex(s);if(++line==failure)throw std::runtime_error("injected");});trace+="|INITIAL:"+dump(model.get());if(bit(32768))AnimationSet::zero_count_bytes->at(0)='!';
 if(!bit(512)){std::string a=bit(1024)?"脚 😃":"a";model->set_animation(a,bit(65536)?std::string("é\0😃",7):bit(1024)?"説明 😃":"A",id(1));model->set_animation("b",bit(2048)?std::optional<std::string>{}:"B",id(2));model->set_animation(a,"Updated",id(3));if(seed&1)model->set_animation(a,{},{});model->set_animation("c",bit(65536)?std::string("é\0😃",7):"C",id(4));if(seed&2)model->set_animation("b",{},{});model->set_animation("d","",id(5));}
 trace+="|BEFORE:"+dump(model.get());if(bit(4096))model->set_animation({},{},{});if(bit(8192))model->animation({});if(bit(16384))model->animation_name({});
 std::function<std::uint32_t(Uuid)> validator=[&](auto anim){trace+="|VAL:"+anim.str();if(bit(1))return 0u;if(bit(2))throw std::runtime_error("injected");if(bit(4))model->set_animation("a",{},{});if(bit(8))model->set_animation("new","New",id(6));if(bit(16))model->set_animation("d","Changed",id(7));if(bit(32))model->set_animation("c",{},{});return bit(262144)?0xffffffffu:bit(524288)?0x80000000u:static_cast<std::uint32_t>(seed*1234567|0x2000);};auto value=model->validate(bit(64)?std::function<std::uint32_t(Uuid)>{}:validator);trace+="|RESULT:"+std::to_string(value);
 }catch(...){status="THROW";}auto result=status+":"+dump(model.get())+trace;AnimationSet::zero_count_bytes->at(0)=saved;return result;}
}
int main(int argc,char**argv){try{if(argc>1&&std::string_view(argv[1])=="--probe"){int m,s,f;while(std::cin>>m>>s>>f)std::cout<<probe(m,s,f)<<'\n';return 0;}int n=0;auto check=[&](bool b,const char*s){++n;if(!b)throw std::runtime_error(s);};check(probe(256|512,0,0).find("|RESULT:2147483647")!=std::string::npos,"constructor does not parse supplied members");check(probe(64|512,0,0).starts_with("OK:"),"empty validation never invokes null delegate");check(probe(64,0,0).starts_with("THROW:"),"populated validation invokes delegate");check(probe(8,0,0).starts_with("THROW:"),"inserting during validation invalidates enumerator");check(probe(4,0,0).starts_with("OK:"),"removing during validation is allowed");std::cout<<"PASS: "<<n<<" animation set checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
